<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import Icon from './Icon.svelte';
	import { uiText as t } from './i18n';
	let {members,editable=false}:{editable?:boolean;members:{id:string;full_name:string}[]}=$props();
	type Account={user_id:string;employee_name:string;bank_code:string;account_number:string;account_name:string;version:number};
	type Column={field:string;label:string};
	const fields:Record<string,string>={employee_code:'Kode karyawan',employee_name:'Nama karyawan',bank_code:'Kode bank',account_number:'Nomor rekening',account_name:'Nama pemilik rekening',net_amount:'Gaji bersih',currency:'Mata uang',period_start:'Awal periode',period_end:'Akhir periode'};
	let accounts=$state<Account[]>([]),columns=$state<Column[]>([{field:'account_number',label:'Account Number'},{field:'account_name',label:'Account Name'},{field:'bank_code',label:'Bank Code'},{field:'net_amount',label:'Amount'}]),delimiter=$state(','),settingsVersion=$state<number|null>(null),confirmed=$state(false);
	let userId=$state(''),bankCode=$state(''),number=$state(''),name=$state(''),busy=$state(false),error=$state(''),notice=$state('');
	let current=$derived(accounts.find(account=>account.user_id===userId));
	async function load(){try{const data=await request<{accounts:Account[];settings:{columns:Column[];delimiter:string;version:number}|null}>('/v1/admin/payroll-bank');accounts=data.accounts;if(data.settings){columns=data.settings.columns;delimiter=data.settings.delimiter;settingsVersion=data.settings.version;}}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}}
	function select(){const entry=accounts.find(account=>account.user_id===userId);bankCode=entry?.bank_code??'';number=entry?.account_number??'';name=entry?.account_name??members.find(member=>member.id===userId)?.full_name??'';}
	async function save(path:string,body:unknown){busy=true;error='';notice='';try{await request(path,{method:'POST',body:JSON.stringify(body)});confirmed=false;await load();notice=t('Konfigurasi tersimpan.');}catch(cause){error=cause instanceof Error?cause.message:t('Gagal menyimpan data.');}finally{busy=false;}}
	function move(index:number,direction:number){const target=index+direction;if(target<0||target>=columns.length)return;const copy=[...columns];[copy[index],copy[target]]=[copy[target],copy[index]];columns=copy;confirmed=false;}
	onMount(load);
</script>
<details class="panel bank"><summary>{t('Rekening dan format ekspor bank')}</summary>{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
	<h2>{t('Rekening karyawan')}</h2><form class="editor-form editor-form--embedded" novalidate onsubmit={event=>{event.preventDefault();void save('/v1/admin/payroll-bank/accounts',{user_id:userId,bank_code:bankCode,account_number:number,account_name:name,version:current?.version??null});}}><label>{t('Karyawan')}<select bind:value={userId} onchange={select} required><option value="">{t('Pilih karyawan')}</option>{#each members as member}<option value={member.id}>{member.full_name}</option>{/each}</select></label><label>{t('Kode bank')}<input bind:value={bankCode} minlength="2" maxlength="20" pattern="[a-zA-Z0-9-]+" required/></label><label>{t('Nomor rekening')}<input bind:value={number} minlength="6" maxlength="40" pattern="[0-9]+" inputmode="numeric" required/></label><label>{t('Nama pemilik rekening')}<input bind:value={name} maxlength="200" required/></label><button disabled={busy||!userId}>{t('Simpan rekening')}</button></form>
	{#if editable}<h2>{t('Format CSV bank')}</h2><p>{t('Cocokkan urutan kolom dan judul dengan template bank. Ekspor tidak mentransfer uang. Rekening dikunci sebagai snapshot saat payroll dipublikasikan.')}</p>
	<form class="editor-form editor-form--embedded" novalidate onsubmit={event=>{event.preventDefault();void save('/v1/admin/payroll-bank/settings',{columns,delimiter,version:settingsVersion,confirmed});}}><label>{t('Pemisah kolom')}<select bind:value={delimiter} onchange={()=>confirmed=false}><option value=",">{t('Koma')}</option><option value=";">{t('Titik koma')}</option></select></label>
		{#each columns as column,index}<div class="column"><label>{t('Data')}<select bind:value={column.field} onchange={()=>confirmed=false}>{#each Object.entries(fields) as [value,label]}<option {value}>{t(label)}</option>{/each}</select></label><label>{t('Judul kolom')}<input bind:value={column.label} maxlength="100" oninput={()=>confirmed=false} required/></label><div class="actions"><button type="button" class="quiet" aria-label={t('Naikkan kolom')} disabled={index===0} onclick={()=>move(index,-1)}><Icon name="up" size={15}/></button><button type="button" class="quiet" aria-label={t('Turunkan kolom')} disabled={index===columns.length-1} onclick={()=>move(index,1)}><Icon name="down" size={15}/></button><button type="button" class="quiet" onclick={()=>{columns=columns.filter((_,i)=>i!==index);confirmed=false;}}>{t('Hapus')}</button></div></div>{/each}
		<button type="button" class="quiet" disabled={columns.length>=20} onclick={()=>{columns=[...columns,{field:'employee_code',label:''}];confirmed=false;}}>{t('Tambah kolom')}</button><label class="confirm"><input type="checkbox" bind:checked={confirmed}/>{t('Saya telah mencocokkan format dengan template bank.')}</label><button disabled={busy||!confirmed}>{t('Simpan format bank')}</button>
	</form>{/if}
</details>
<style>.bank{padding:16px;border-radius:var(--radius)}summary{font-size:13px;font-weight:700;cursor:pointer}h2{font-size:14px;margin:18px 0 10px}p{font-size:12px;color:var(--muted)}form{display:grid;gap:10px}.column{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding-block:8px;border-bottom:1px solid var(--line)}.actions{grid-column:1/-1;display:flex;gap:6px}.confirm{display:flex;align-items:center;gap:8px}.confirm input{width:auto}</style>
